const int MAX_STEPS=1000;
const float MIN_DISTANCE=0.0001;
const float MAX_DISTANCE=100.0;
const int MAX_STEPS_SHADOWS=100;

const int MAX_BOUNCE=2;

//distances
//sphere
float dis_sphere(vec3 point, vec3 center, float radious){
    return distance(point,center)-radious;
}
float dis_cube(vec3 ray, vec3 center, vec3 dim){
    vec3 point = abs(center - ray) - dim;
    return length(max(point, 0.0)) + min(max(point.x, max(point.y, point.z)), 0.0);
}

//booleans
//union
float OR(float a, float b){
    return min(a,b);
}
//cut
float NOT(float a, float b){
    return max(a,-b);
}
//intesection
float AND(float a, float b){
    return max(a,b);
}

//scene
float dis_scene(vec3 point){
    float sp1=dis_sphere(point,vec3(0.0,0.0,3.0),2.0);
    float sp2=dis_sphere(point,vec3(2.0,1.0,4.0),2.0);
    float sp3=dis_sphere(point,vec3(2.0,-1.0,3.0),1.0);
    float cu1=dis_cube(point,vec3(7.0,1.0,3.0),vec3(3.0));
    float cu2=dis_cube(point,vec3(0.0,-12.0,0.0),vec3(10.0));
    return OR(OR(NOT(OR(sp1,sp2),sp3),cu1),cu2);
}

//utils
vec3 normal_vec(vec3 p){
    const float epsilon=0.0001;
    const vec2 E=vec2(0.0,epsilon);
    return normalize(vec3(
        dis_scene(p+E.yxx)-dis_scene(p-E.yxx),
        dis_scene(p+E.xyx)-dis_scene(p-E.xyx),
        dis_scene(p+E.xxy)-dis_scene(p-E.xxy)
    ));
}

float shadow(vec3 point, vec3 dir){
    float shad=1.0;
    float distot = 0.1;
    for (int i=0; i<MAX_STEPS_SHADOWS; i++){
        vec3 ray=point+dir*distot;
        float dis=dis_scene(ray);
        shad = min(shad,dis/distot);
        distot+=clamp(dis,0.0,0.6);
    }
    return clamp(shad*2.0,0.0,1.0);
}

//ray
vec3 ray(vec3 ori, vec3 dir){
    //vec3 col=vec3(0.0);
    float distot=0.0;

    for (int paso=0; paso<MAX_STEPS; paso++){
        vec3 ray = ori + dir*distot;
        float dist=dis_scene(ray);

        distot+=dist;

        if (dist<MIN_DISTANCE){
            ray = ori + dir*distot;
            //float lumi=shadow(ray,normalize(vec3(0.0,0.5,-1.0)));
            //col=vec3(max(lumi,0.2)*vec3(0.0,0.5,1.0));
            //break;
            return ray;
        }

        if (distot>MAX_DISTANCE){
            break;
        }
    }

    return ori;//col;
}

vec3 reflections(vec3 ori, vec3 dir){
    vec3 col=vec3(0.0);
    for (int bounces=0; bounces<MAX_BOUNCE; bounces++){
        vec3 hit=ray(ori,dir);
        vec3 normal=normal_vec(hit);

        float lumi=shadow(hit,normalize(vec3(0.0,0.5,-1.0)));

        if (hit!=ori){
            col+=vec3(max(lumi,0.0)*vec3(0.0,0.5,1.0))*pow(float(MAX_BOUNCE-bounces)/float(MAX_BOUNCE),2.0);
        }else{
            col+=texture(iChannel0,dir.xy).rgb*0.2;
            break;
        }

        dir=reflect(dir,normal);
        ori=hit+dir*0.001;
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float fov=60.0;
    float aspect_ratio=iResolution.y/iResolution.x;
    float sc = tan(fov*0.5*3.14159265359/180.0);

    vec2 p=(fragCoord/iResolution.xy*2.0-1.0)*sc;
    p.x/=aspect_ratio;

    vec3 dir=normalize(vec3(p,1.0));

    vec3 ori=vec3(2.0,1.0,-7.0)+vec3(cos(iTime),0.0,sin(iTime))*5.0;

    fragColor=vec4(reflections(ori,dir),1.0);
    //fragColor=vec4(fragCoord/iResolution.xy*2.0-1.0,0.0,1.0);
}
